-- Тема 17: правки по отчёту Codex (35 исправлений в 15 вопросах), ключи не меняются.
-- Источник: scripts/questions/089_codex_topic17_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Мешает ли работающий pg_dump другим сеансам?', NULL, NULL, NULL, 'Мешает ли работающий pg_dump другим сеансам при работе с выгружаемыми таблицами?'),
        ('question', 'Что нужно для восстановления кластера на момент в прошлом (PITR)?', NULL, NULL, NULL, 'Что нужно для восстановления кластера на выбранный момент после окончания базовой копии (PITR)?'),
        ('question', 'Можно ли восстановиться из базовой копии на момент раньше окончания её создания?', NULL, NULL, NULL, 'Можно ли при PITR из горячей базовой копии выбрать цель раньше окончания её создания?'),
        ('question', 'Чем опасны сеансы в состоянии idle in transaction?', NULL, NULL, NULL, 'Чем опасны сеансы в состоянии idle in transaction при настройках по умолчанию?'),
        ('question', 'Что будет при synchronous_commit = off и сбое сервера?', NULL, NULL, NULL, 'Что будет при synchronous_commit = off и сбое сервера, если остальные настройки надёжности штатные?'),
        ('question', 'Какие значения synchronous_commit заставляют фиксацию ждать синхронную реплику?', NULL, NULL, NULL, 'Какие значения synchronous_commit заставляют фиксацию ждать синхронную реплику при настроенной синхронной репликации?'),
        ('question', 'Какую команду нельзя выполнить внутри блока транзакции?', NULL, NULL, NULL, 'Какую из этих команд нельзя выполнить внутри явного блока транзакции (таблица t(id integer) существует, имена demo и t_copy свободны)?'),
        ('question', 'Как в штатном режиме обновляется статистика для планировщика?', NULL, NULL, NULL, 'Как автоматически обновляется статистика обычной постоянной таблицы при включённой автоочистке?'),
        ('option', 'Чем физическая резервная копия отличается от логической (дампа)?', 'Логическая копия восстанавливается быстрее, чем физическая', 'Логический дамп восстанавливают воспроизведением WAL', 'Наоборот: при восстановлении из дампа выполняются все команды, включая построение индексов.', 'Дамп состоит из команд SQL или архива pg_dump, а WAL для него не применяется.'),
        ('option', 'Мешает ли работающий pg_dump другим сеансам при работе с выгружаемыми таблицами?', 'Чтение и запись идут, но DROP и ALTER TABLE ждут', 'Чтение и запись идут, DDL с ACCESS EXCLUSIVE ждёт', 'Чтение и изменение данных не блокируются, но DROP TABLE и большинство форм ALTER TABLE для выгружаемых таблиц будут ждать: pg_dump берёт блокировки ACCESS SHARE и держит их до конца выгрузки.', 'Чтение и изменение данных не блокируются, но DROP TABLE и большинство форм ALTER TABLE для выгружаемых таблиц будут ждать: pg_dump берёт блокировки ACCESS SHARE и держит их до конца выгрузки. Ожидающая команда может создать очередь и задержать последующие запросы к таблице.'),
        ('option', 'Чем горячее физическое резервное копирование файлов кластера отличается от холодного?', 'Горячее копирование берёт файлы кластера без журналов WAL', 'Горячая копия восстанавливается без использования WAL', 'Горячей копии как раз нужны журналы WAL за время копирования.', 'Для согласования горячей копии нужен WAL: он может лежать в самой копии или поступать из отдельного архива.'),
        ('option', 'Чем горячее физическое резервное копирование файлов кластера отличается от холодного?', 'Холодной копии нужен архив журналов WAL', NULL, 'Копия аккуратно остановленного сервера согласованна и журналов не требует.', 'После штатной остановки внешний архив WAL не нужен, но каталог pg_wal сохраняют в составе холодной копии.'),
        ('option', 'Что нужно для восстановления кластера на выбранный момент после окончания базовой копии (PITR)?', 'Базовая копия без архива журналов', 'Базовая копия без WAL до выбранной цели', 'Без архива журналов автономная копия восстанавливается только на момент окончания её создания.', 'Нужна непрерывная цепочка необходимого WAL: автономная базовая копия сама по себе не восстанавливается на произвольную более позднюю цель.'),
        ('option', 'Что нужно для восстановления кластера на выбранный момент после окончания базовой копии (PITR)?', 'Свежий дамп pg_dump на нужный момент', 'Дамп pg_dump и архив WAL до выбранной цели', 'Дамп восстанавливается только на момент его создания.', 'Дамп восстанавливается только на момент его создания, а WAL к нему применить нельзя.'),
        ('option', 'Что гарантирует synchronous_commit = remote_write при синхронной реплике?', 'Реплика получила записи и передала их ОС', NULL, 'Реплика получила записи и передала их ОС, но на диск они ещё могут быть не сброшены: данные переживут сбой процесса PostgreSQL на реплике, но не сбой её ОС.', 'Реплика получила записи и передала их ОС, но на диск они могли ещё не попасть: при сбое ОС реплики сохранность данных на ней не гарантируется.'),
        ('option', 'Что будет при synchronous_commit = off и сбое сервера, если остальные настройки надёжности штатные?', 'База может оказаться повреждённой после такого сбоя', NULL, 'Повреждения не будет: журнал записывается в правильном порядке.', 'Само отключение синхронного подтверждения повреждения не вызывает: журнал записывается в правильном порядке.'),
        ('option', 'Какую из этих команд нельзя выполнить внутри явного блока транзакции (таблица t(id integer) существует, имена demo и t_copy свободны)?', '`CREATE DATABASE`', '`CREATE DATABASE demo TEMPLATE template0;`', NULL, NULL),
        ('option', 'Какую из этих команд нельзя выполнить внутри явного блока транзакции (таблица t(id integer) существует, имена demo и t_copy свободны)?', '`TRUNCATE TABLE`', '`TRUNCATE TABLE t RESTART IDENTITY;`', 'В PostgreSQL она транзакционна.', 'В PostgreSQL TRUNCATE транзакционна: её можно откатить.'),
        ('option', 'Какую из этих команд нельзя выполнить внутри явного блока транзакции (таблица t(id integer) существует, имена demo и t_copy свободны)?', '`ALTER TABLE`', '`ALTER TABLE t ADD COLUMN note text;`', 'Большинство её форм можно выполнить и откатить; исключение — DETACH PARTITION CONCURRENTLY.', 'Форма ADD COLUMN выполняется в транзакции и откатывается; исключением среди форм ALTER TABLE остаётся DETACH PARTITION CONCURRENTLY.'),
        ('option', 'Какую из этих команд нельзя выполнить внутри явного блока транзакции (таблица t(id integer) существует, имена demo и t_copy свободны)?', '`CREATE TABLE AS`', '`CREATE TABLE t_copy AS SELECT id FROM t;`', NULL, NULL),
        ('explanation', 'Какую из этих команд нельзя выполнить внутри явного блока транзакции (таблица t(id integer) существует, имена demo и t_copy свободны)?', NULL, NULL, 'CREATE DATABASE запрещена внутри явного блока транзакции; для перечисленных обычных форм CREATE TABLE, ALTER TABLE и TRUNCATE такого общего запрета нет.', 'CREATE DATABASE запрещена внутри явного блока транзакции; CREATE TABLE AS, TRUNCATE и ALTER TABLE … ADD COLUMN выполняются в транзакции и откатываются.'),
        ('option', 'Уменьшится ли размер файла таблицы на диске после DELETE и VACUUM?', 'Да, сразу после выполнения DELETE', 'Обычно да, сразу после выполнения DELETE', NULL, NULL),
        ('option', 'Уменьшится ли размер файла таблицы на диске после DELETE и VACUUM?', 'Да, после следующей контрольной точки', 'Обычно да, после следующей контрольной точки', NULL, NULL),
        ('option', 'Уменьшится ли размер файла таблицы на диске после DELETE и VACUUM?', 'Да, VACUUM сжимает файл до размера данных', 'Обычно да, VACUUM сжимает файл до размера данных', NULL, NULL),
        ('option', 'Чем общий план подготовленного оператора отличается от частного?', 'Частный план сохраняется на диске сервера', 'Частный сохраняется на диске, общий — в памяти сеанса', NULL, NULL),
        ('option', 'Чем общий план подготовленного оператора отличается от частного?', 'Разницы нет: это один и тот же план', 'Общий учитывает значения параметров, частный — нет', 'Для неравномерных данных планы могут сильно различаться.', 'Наоборот: частный план строится с учётом конкретных значений параметров, общий — без них.'),
        ('option', 'Чем общий план подготовленного оператора отличается от частного?', 'Общий план строится для всех баз кластера', 'Частный строится для всех баз кластера, общий — для одной', NULL, NULL),
        ('option', 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', 'После выполнения ANALYZE этой таблицы', 'После ANALYZE, если общий план стал дешевле частных', 'ANALYZE лишь делает план недействительным для перестроения.', 'ANALYZE лишь делает план недействительным для перестроения, правила перехода он не задаёт.'),
        ('option', 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', 'Сразу при первом выполнении оператора', 'Сразу при первом выполнении, если общий план дешевле', NULL, NULL),
        ('option', 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', 'Не переходит, пока не задан force_generic_plan', 'Не переходит, пока не задан режим force_generic_plan', NULL, NULL),
        ('option', 'Как автоматически обновляется статистика обычной постоянной таблицы при включённой автоочистке?', 'Вручную командой ANALYZE администратором', 'Планировщик сам запускает ANALYZE при построении плана', 'Обычно её запускает автоочистка; вручную ANALYZE выполняют при необходимости, но это не штатный путь.', 'Планировщик только читает собранную статистику и ANALYZE не запускает; вручную ANALYZE допустим, но вопрос об автоматическом обновлении.'),
        ('option', 'Как автоматически обновляется статистика обычной постоянной таблицы при включённой автоочистке?', 'Автоочистка запускает ANALYZE после изменений', 'Автоочистка запускает ANALYZE при достижении порога', NULL, NULL),
        ('explanation', 'Как автоматически обновляется статистика обычной постоянной таблицы при включённой автоочистке?', NULL, NULL, 'Автоочистка запускает ANALYZE, когда число изменений таблицы превышает порог, зависящий от threshold и scale_factor.', 'Автоочистка запускает ANALYZE, когда число изменений таблицы превышает порог, зависящий от threshold и scale_factor. Ручной ANALYZE также допустим; для временных и родительских секционированных таблиц нужен отдельный анализ.'),
        ('option', 'Зачем нужна команда CREATE STATISTICS?', 'Посмотреть собранную статистику по таблице', NULL, 'Для этого есть pg_stats и представления pg_stat_*.', 'Для этого есть pg_stats, pg_stats_ext и накопительные представления pg_stat_*.'),
        ('option', 'Зачем нужна команда CREATE STATISTICS?', 'Собирать статистику по связям нескольких столбцов', 'Объявить расширенную статистику по столбцам', 'Собирает расширенную статистику по нескольким столбцам, например их зависимость: обычная статистика считает столбцы независимыми и ошибается для связанных.', 'Команда объявляет объект расширенной статистики, например для зависимости значений нескольких столбцов; данные для него собирает ANALYZE, а обычная статистика считает столбцы независимыми.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
